CREATE TABLE IF NOT EXISTS "airports" (
	-- Surrogate primary key. IATA codes get reassigned, so they do not make a safe key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Three-letter IATA code, e.g. LHR. What passengers read on a boarding pass.
	"iata_code" CHAR(3) NOT NULL UNIQUE,
	-- Four-letter ICAO code, e.g. EGLL. Used by operations and flight planning, not by ticketing.
	"icao_code" CHAR(4) UNIQUE,
	-- Full airport name.
	"name" VARCHAR(160) NOT NULL,
	-- City served, which is not always the city the airport sits in.
	"city" VARCHAR(120) NOT NULL,
	-- ISO 3166-1 alpha-2 country code, used for visa and customs rules.
	"country_code" CHAR(2) NOT NULL,
	-- IANA zone. Every scheduled time in this schema is local to its airport, so nothing works without this.
	"timezone" VARCHAR(64) NOT NULL,
	-- Position, used for distance-based fare and mileage calculations.
	"latitude" NUMERIC(9,6),
	-- Position, used for distance-based fare and mileage calculations.
	"longitude" NUMERIC(9,6),
	-- False retires an airport without orphaning decades of history.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "airports" IS 'Reference data with a timezone attached. Departure and arrival times in this schema are local wall-clock values, because that is what a timetable publishes and what a passenger reads; converting them to instants requires this row.';
COMMENT ON COLUMN "airports"."id" IS 'Surrogate primary key. IATA codes get reassigned, so they do not make a safe key.';
COMMENT ON COLUMN "airports"."iata_code" IS 'Three-letter IATA code, e.g. LHR. What passengers read on a boarding pass.';
COMMENT ON COLUMN "airports"."icao_code" IS 'Four-letter ICAO code, e.g. EGLL. Used by operations and flight planning, not by ticketing.';
COMMENT ON COLUMN "airports"."name" IS 'Full airport name.';
COMMENT ON COLUMN "airports"."city" IS 'City served, which is not always the city the airport sits in.';
COMMENT ON COLUMN "airports"."country_code" IS 'ISO 3166-1 alpha-2 country code, used for visa and customs rules.';
COMMENT ON COLUMN "airports"."timezone" IS 'IANA zone. Every scheduled time in this schema is local to its airport, so nothing works without this.';
COMMENT ON COLUMN "airports"."latitude" IS 'Position, used for distance-based fare and mileage calculations.';
COMMENT ON COLUMN "airports"."longitude" IS 'Position, used for distance-based fare and mileage calculations.';
COMMENT ON COLUMN "airports"."is_active" IS 'False retires an airport without orphaning decades of history.';

CREATE INDEX "idx_airports_city_country"
ON "airports" ("city", "country_code");

CREATE TABLE IF NOT EXISTS "aircraft_configurations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Internal layout code, e.g. 738-V2. One airframe type often flies several layouts.
	"code" VARCHAR(24) NOT NULL UNIQUE,
	-- Equipment type, e.g. B738 or A20N.
	"aircraft_type" VARCHAR(24) NOT NULL,
	-- Human label, e.g. 737-800 two class with extra legroom rows.
	"description" VARCHAR(160),
	-- Seat count across all cabins, cached so capacity planning does not count the seat map every time.
	"total_seats" SMALLINT NOT NULL,
	-- Amenity shown at booking, and a real differentiator on long haul.
	"has_wifi" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "aircraft_configurations" IS 'A seating layout, not an airframe. The same registration can be reconfigured, and two aircraft of the same type can have different seat maps, so inventory and seat selection key on the layout rather than on a tail number.';
COMMENT ON COLUMN "aircraft_configurations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "aircraft_configurations"."code" IS 'Internal layout code, e.g. 738-V2. One airframe type often flies several layouts.';
COMMENT ON COLUMN "aircraft_configurations"."aircraft_type" IS 'Equipment type, e.g. B738 or A20N.';
COMMENT ON COLUMN "aircraft_configurations"."description" IS 'Human label, e.g. 737-800 two class with extra legroom rows.';
COMMENT ON COLUMN "aircraft_configurations"."total_seats" IS 'Seat count across all cabins, cached so capacity planning does not count the seat map every time.';
COMMENT ON COLUMN "aircraft_configurations"."has_wifi" IS 'Amenity shown at booking, and a real differentiator on long haul.';

CREATE TABLE IF NOT EXISTS "cabin_seats" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Layout this seat belongs to.
	"configuration_id" BIGINT NOT NULL,
	-- Row and letter as printed in the cabin, e.g. 14C.
	"seat_number" VARCHAR(5) NOT NULL,
	-- economy | premium_economy | business | first. The physical cabin, which is not the same thing as the fare class booked.
	"cabin" VARCHAR(16) NOT NULL,
	-- window | middle | aisle. Drives the seat picker and the price of a paid seat.
	"seat_type" VARCHAR(16) NOT NULL,
	-- Exit rows carry legal restrictions on who may sit there, checked at assignment time.
	"is_exit_row" BOOLEAN NOT NULL DEFAULT false,
	-- Bulkhead seats take bassinets and have no seat in front to recline into.
	"is_bulkhead" BOOLEAN NOT NULL DEFAULT false,
	-- Charged as a paid seat on most carriers.
	"extra_legroom" BOOLEAN NOT NULL DEFAULT false,
	-- Permanently unavailable, e.g. a crew rest seat. Distinct from being sold.
	"is_blocked" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cabin_seats" IS 'The seat map, stored once per layout rather than once per departure. A 737 flying four times a day does not need four copies of the same 189 rows; what varies per departure is which of these seats is taken, and that lives in seat_assignments.';
COMMENT ON COLUMN "cabin_seats"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cabin_seats"."configuration_id" IS 'Layout this seat belongs to.';
COMMENT ON COLUMN "cabin_seats"."seat_number" IS 'Row and letter as printed in the cabin, e.g. 14C.';
COMMENT ON COLUMN "cabin_seats"."cabin" IS 'economy | premium_economy | business | first. The physical cabin, which is not the same thing as the fare class booked.';
COMMENT ON COLUMN "cabin_seats"."seat_type" IS 'window | middle | aisle. Drives the seat picker and the price of a paid seat.';
COMMENT ON COLUMN "cabin_seats"."is_exit_row" IS 'Exit rows carry legal restrictions on who may sit there, checked at assignment time.';
COMMENT ON COLUMN "cabin_seats"."is_bulkhead" IS 'Bulkhead seats take bassinets and have no seat in front to recline into.';
COMMENT ON COLUMN "cabin_seats"."extra_legroom" IS 'Charged as a paid seat on most carriers.';
COMMENT ON COLUMN "cabin_seats"."is_blocked" IS 'Permanently unavailable, e.g. a crew rest seat. Distinct from being sold.';

CREATE UNIQUE INDEX "uq_cabin_seats_config_number"
ON "cabin_seats" ("configuration_id", "seat_number");

CREATE TABLE IF NOT EXISTS "flights" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- IATA airline code, e.g. BA.
	"carrier_code" CHAR(2) NOT NULL,
	-- Number without the carrier prefix. BA and 117 together are what a passenger calls the flight.
	"flight_number" VARCHAR(5) NOT NULL,
	-- First date the schedule is valid. Schedules are republished each season rather than edited in place.
	"effective_from" DATE NOT NULL,
	-- Last date the schedule is valid.
	"effective_to" DATE NOT NULL,
	-- Operating days as digits, 1 for Monday. A Tuesday and Thursday service is stored as 24, which is what makes the weekly pattern expressible without a row per date.
	"days_of_week" VARCHAR(7) NOT NULL DEFAULT '1234567',
	-- Planned seating layout, and therefore the planned capacity.
	"configuration_id" BIGINT NOT NULL,
	-- False withdraws the service from sale without deleting the dated departures already booked on it.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flights" IS 'A scheduled service as published in the timetable: a number, a season and a weekly pattern. It is not a thing that flies. The dated instances are generated from the pattern into flight_departures, which is where operations and inventory actually happen.';
COMMENT ON COLUMN "flights"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "flights"."carrier_code" IS 'IATA airline code, e.g. BA.';
COMMENT ON COLUMN "flights"."flight_number" IS 'Number without the carrier prefix. BA and 117 together are what a passenger calls the flight.';
COMMENT ON COLUMN "flights"."effective_from" IS 'First date the schedule is valid. Schedules are republished each season rather than edited in place.';
COMMENT ON COLUMN "flights"."effective_to" IS 'Last date the schedule is valid.';
COMMENT ON COLUMN "flights"."days_of_week" IS 'Operating days as digits, 1 for Monday. A Tuesday and Thursday service is stored as 24, which is what makes the weekly pattern expressible without a row per date.';
COMMENT ON COLUMN "flights"."configuration_id" IS 'Planned seating layout, and therefore the planned capacity.';
COMMENT ON COLUMN "flights"."is_active" IS 'False withdraws the service from sale without deleting the dated departures already booked on it.';

CREATE UNIQUE INDEX "uq_flights_number_season"
ON "flights" ("carrier_code", "flight_number", "effective_from");

CREATE TABLE IF NOT EXISTS "flight_legs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Service this leg belongs to.
	"flight_id" BIGINT NOT NULL,
	-- Position in the routing, starting at 1. A one-stop service under a single number is two legs.
	"leg_sequence" SMALLINT NOT NULL,
	-- Departure airport for this leg.
	"origin_airport_id" BIGINT NOT NULL,
	-- Arrival airport for this leg.
	"destination_airport_id" BIGINT NOT NULL,
	-- Scheduled departure, local to the origin airport.
	"departure_time" TIME NOT NULL,
	-- Scheduled arrival, local to the destination airport.
	"arrival_time" TIME NOT NULL,
	-- Days added to the departure date to get the arrival date. 1 for an overnight, and the single most commonly forgotten column in airline schemas.
	"arrival_day_offset" SMALLINT NOT NULL DEFAULT 0,
	-- Scheduled gate-to-gate duration, which is the only duration that survives crossing timezones.
	"block_minutes" SMALLINT NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flight_legs" IS 'One row per hop of the published routing. Legs exist because a single flight number can serve two hops, and because a passenger may buy only the second one; inventory and seats are therefore always per leg, never per flight number.';
COMMENT ON COLUMN "flight_legs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "flight_legs"."flight_id" IS 'Service this leg belongs to.';
COMMENT ON COLUMN "flight_legs"."leg_sequence" IS 'Position in the routing, starting at 1. A one-stop service under a single number is two legs.';
COMMENT ON COLUMN "flight_legs"."origin_airport_id" IS 'Departure airport for this leg.';
COMMENT ON COLUMN "flight_legs"."destination_airport_id" IS 'Arrival airport for this leg.';
COMMENT ON COLUMN "flight_legs"."departure_time" IS 'Scheduled departure, local to the origin airport.';
COMMENT ON COLUMN "flight_legs"."arrival_time" IS 'Scheduled arrival, local to the destination airport.';
COMMENT ON COLUMN "flight_legs"."arrival_day_offset" IS 'Days added to the departure date to get the arrival date. 1 for an overnight, and the single most commonly forgotten column in airline schemas.';
COMMENT ON COLUMN "flight_legs"."block_minutes" IS 'Scheduled gate-to-gate duration, which is the only duration that survives crossing timezones.';

CREATE UNIQUE INDEX "uq_flight_legs_flight_sequence"
ON "flight_legs" ("flight_id", "leg_sequence");
CREATE INDEX "idx_flight_legs_route"
ON "flight_legs" ("origin_airport_id", "destination_airport_id");

CREATE TABLE IF NOT EXISTS "flight_departures" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Scheduled leg being operated.
	"flight_leg_id" BIGINT NOT NULL,
	-- Local calendar date at the origin airport. With the leg, this is the unique identity of a real flight.
	"departure_date" DATE NOT NULL,
	-- Layout actually assigned. Copied from the flight so an equipment swap changes the seat map for one date only.
	"configuration_id" BIGINT NOT NULL,
	-- Registration of the airframe assigned. Null until operations allocate one, often the day before.
	"tail_number" VARCHAR(10),
	-- scheduled | delayed | boarding | departed | landed | cancelled | diverted.
	"status" VARCHAR(24) NOT NULL DEFAULT 'scheduled',
	-- The timetable time resolved to an instant using the origin timezone. Stored so sorting and comparison do not need a timezone join.
	"scheduled_departure_at" TIMESTAMPTZ NOT NULL,
	-- Off-blocks time. The gap from scheduled is the on-time performance figure.
	"actual_departure_at" TIMESTAMPTZ,
	-- On-blocks time at the destination.
	"actual_arrival_at" TIMESTAMPTZ,
	-- Departure gate, assigned late and changed often.
	"gate" VARCHAR(8),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "flight_departures" IS 'A leg on a specific date: the thing that actually flies, that seats are assigned on and that can be delayed. Everything downstream references this rather than the schedule, because a schedule cannot be cancelled but a Tuesday can.';
COMMENT ON COLUMN "flight_departures"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "flight_departures"."flight_leg_id" IS 'Scheduled leg being operated.';
COMMENT ON COLUMN "flight_departures"."departure_date" IS 'Local calendar date at the origin airport. With the leg, this is the unique identity of a real flight.';
COMMENT ON COLUMN "flight_departures"."configuration_id" IS 'Layout actually assigned. Copied from the flight so an equipment swap changes the seat map for one date only.';
COMMENT ON COLUMN "flight_departures"."tail_number" IS 'Registration of the airframe assigned. Null until operations allocate one, often the day before.';
COMMENT ON COLUMN "flight_departures"."status" IS 'scheduled | delayed | boarding | departed | landed | cancelled | diverted.';
COMMENT ON COLUMN "flight_departures"."scheduled_departure_at" IS 'The timetable time resolved to an instant using the origin timezone. Stored so sorting and comparison do not need a timezone join.';
COMMENT ON COLUMN "flight_departures"."actual_departure_at" IS 'Off-blocks time. The gap from scheduled is the on-time performance figure.';
COMMENT ON COLUMN "flight_departures"."actual_arrival_at" IS 'On-blocks time at the destination.';
COMMENT ON COLUMN "flight_departures"."gate" IS 'Departure gate, assigned late and changed often.';

CREATE UNIQUE INDEX "uq_departures_leg_date"
ON "flight_departures" ("flight_leg_id", "departure_date");
CREATE INDEX "idx_departures_date_status"
ON "flight_departures" ("departure_date", "status");

CREATE TABLE IF NOT EXISTS "fare_classes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Single-letter booking class, e.g. Y, M, Q, J. This letter, not the cabin, is what determines the rules and the price.
	"code" CHAR(1) NOT NULL UNIQUE,
	-- economy | premium_economy | business | first. Several classes map to one cabin, which is the whole point of the letter.
	"cabin" VARCHAR(16) NOT NULL,
	-- Marketing name, e.g. Economy Saver.
	"display_name" VARCHAR(60) NOT NULL,
	-- Whether the fare can be refunded rather than only changed.
	"is_refundable" BOOLEAN NOT NULL DEFAULT false,
	-- Fee to change a ticket on this class, in minor units.
	"change_fee_minor" INTEGER NOT NULL DEFAULT 0,
	-- Free checked bags. Anything beyond this becomes an ancillary row.
	"checked_bags_included" SMALLINT NOT NULL DEFAULT 0,
	-- Loyalty miles earned as a percent of distance flown. Deep discount classes often earn 25.
	"mileage_earning_percent" SMALLINT NOT NULL DEFAULT 100,
	-- Lower boards earlier. Determines group number on the boarding pass.
	"boarding_priority" SMALLINT NOT NULL DEFAULT 5,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "fare_classes" IS 'The commercial product behind the letter. Two passengers in adjacent economy seats on the same leg can be in J and Q with completely different refund, change and baggage rights, which is why the class is not just a label on the cabin.';
COMMENT ON COLUMN "fare_classes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "fare_classes"."code" IS 'Single-letter booking class, e.g. Y, M, Q, J. This letter, not the cabin, is what determines the rules and the price.';
COMMENT ON COLUMN "fare_classes"."cabin" IS 'economy | premium_economy | business | first. Several classes map to one cabin, which is the whole point of the letter.';
COMMENT ON COLUMN "fare_classes"."display_name" IS 'Marketing name, e.g. Economy Saver.';
COMMENT ON COLUMN "fare_classes"."is_refundable" IS 'Whether the fare can be refunded rather than only changed.';
COMMENT ON COLUMN "fare_classes"."change_fee_minor" IS 'Fee to change a ticket on this class, in minor units.';
COMMENT ON COLUMN "fare_classes"."checked_bags_included" IS 'Free checked bags. Anything beyond this becomes an ancillary row.';
COMMENT ON COLUMN "fare_classes"."mileage_earning_percent" IS 'Loyalty miles earned as a percent of distance flown. Deep discount classes often earn 25.';
COMMENT ON COLUMN "fare_classes"."boarding_priority" IS 'Lower boards earlier. Determines group number on the boarding pass.';

CREATE TABLE IF NOT EXISTS "inventory_buckets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Dated leg being sold.
	"departure_id" BIGINT NOT NULL,
	-- Class being sold on that leg.
	"fare_class_id" BIGINT NOT NULL,
	-- Seats revenue management has released to this class. Buckets deliberately overlap, so the sum across classes usually exceeds the physical cabin.
	"authorised_seats" SMALLINT NOT NULL DEFAULT 0,
	-- Seats confirmed in this class. Incremented in the same transaction that confirms a segment.
	"sold_seats" SMALLINT NOT NULL DEFAULT 0,
	-- Passengers queued for a seat that has not opened yet.
	"waitlist_seats" SMALLINT NOT NULL DEFAULT 0,
	-- Current one-way price for the class on this leg, in minor units. Moves continuously as the bucket fills.
	"price_minor" INTEGER NOT NULL,
	-- ISO 4217 currency of price_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Stop-sell for the class, independent of remaining authorisation. Revenue management closes cheap buckets long before they are full.
	"is_closed" BOOLEAN NOT NULL DEFAULT false,
	-- Last repricing, used to expire cached search results.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "inventory_buckets" IS 'Availability per class per dated leg, which is what an airline actually sells. Buckets are nested rather than partitioned: selling one seat in Y can shut several cheaper classes at once, so the physical seat count is a ceiling on the total, not on any single bucket.';
COMMENT ON COLUMN "inventory_buckets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "inventory_buckets"."departure_id" IS 'Dated leg being sold.';
COMMENT ON COLUMN "inventory_buckets"."fare_class_id" IS 'Class being sold on that leg.';
COMMENT ON COLUMN "inventory_buckets"."authorised_seats" IS 'Seats revenue management has released to this class. Buckets deliberately overlap, so the sum across classes usually exceeds the physical cabin.';
COMMENT ON COLUMN "inventory_buckets"."sold_seats" IS 'Seats confirmed in this class. Incremented in the same transaction that confirms a segment.';
COMMENT ON COLUMN "inventory_buckets"."waitlist_seats" IS 'Passengers queued for a seat that has not opened yet.';
COMMENT ON COLUMN "inventory_buckets"."price_minor" IS 'Current one-way price for the class on this leg, in minor units. Moves continuously as the bucket fills.';
COMMENT ON COLUMN "inventory_buckets"."currency_code" IS 'ISO 4217 currency of price_minor.';
COMMENT ON COLUMN "inventory_buckets"."is_closed" IS 'Stop-sell for the class, independent of remaining authorisation. Revenue management closes cheap buckets long before they are full.';
COMMENT ON COLUMN "inventory_buckets"."updated_at" IS 'Last repricing, used to expire cached search results.';

CREATE UNIQUE INDEX "uq_inventory_departure_class"
ON "inventory_buckets" ("departure_id", "fare_class_id");
CREATE INDEX "idx_inventory_open_buckets"
ON "inventory_buckets" ("departure_id", "is_closed");

CREATE TABLE IF NOT EXISTS "bookings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The PNR code a passenger quotes, six alphanumeric characters. Reused after a few years, which is why it is not the primary key.
	"record_locator" CHAR(6) NOT NULL UNIQUE,
	-- held | ticketed | partially_flown | flown | cancelled. A held booking has seats but no money.
	"status" VARCHAR(24) NOT NULL DEFAULT 'held',
	-- Address every itinerary change and irregular-operation notice goes to.
	"contact_email" VARCHAR(320) NOT NULL,
	-- Number used for day-of-travel disruption contact.
	"contact_phone" VARCHAR(32),
	-- Currency the itinerary was priced in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Sum of ticket fares and ancillaries, in minor units. A held booking has a price but no payment.
	"total_minor" INTEGER NOT NULL DEFAULT 0,
	-- web | mobile | agency | gds | call_centre. Drives commission and servicing rules.
	"booking_channel" VARCHAR(24) NOT NULL DEFAULT 'web',
	-- When an unticketed booking is auto-cancelled and its seats returned to inventory. Null once ticketed.
	"ticketing_deadline" TIMESTAMPTZ,
	-- When the booking was created.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Cancellation time. Rows are kept because a cancelled PNR is still evidence in a refund dispute.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "bookings" IS 'The reservation record: an itinerary, a set of passengers and a contact, under one record locator. It holds seats, not money. A booking can exist fully valid and entirely unpaid until its ticketing deadline expires.';
COMMENT ON COLUMN "bookings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "bookings"."record_locator" IS 'The PNR code a passenger quotes, six alphanumeric characters. Reused after a few years, which is why it is not the primary key.';
COMMENT ON COLUMN "bookings"."status" IS 'held | ticketed | partially_flown | flown | cancelled. A held booking has seats but no money.';
COMMENT ON COLUMN "bookings"."contact_email" IS 'Address every itinerary change and irregular-operation notice goes to.';
COMMENT ON COLUMN "bookings"."contact_phone" IS 'Number used for day-of-travel disruption contact.';
COMMENT ON COLUMN "bookings"."currency_code" IS 'Currency the itinerary was priced in.';
COMMENT ON COLUMN "bookings"."total_minor" IS 'Sum of ticket fares and ancillaries, in minor units. A held booking has a price but no payment.';
COMMENT ON COLUMN "bookings"."booking_channel" IS 'web | mobile | agency | gds | call_centre. Drives commission and servicing rules.';
COMMENT ON COLUMN "bookings"."ticketing_deadline" IS 'When an unticketed booking is auto-cancelled and its seats returned to inventory. Null once ticketed.';
COMMENT ON COLUMN "bookings"."created_at" IS 'When the booking was created.';
COMMENT ON COLUMN "bookings"."cancelled_at" IS 'Cancellation time. Rows are kept because a cancelled PNR is still evidence in a refund dispute.';

CREATE INDEX "idx_bookings_ticketing_sweep"
ON "bookings" ("status", "ticketing_deadline");
CREATE INDEX "idx_bookings_contact_email"
ON "bookings" ("contact_email");

CREATE TABLE IF NOT EXISTS "passengers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Booking the passenger travels under.
	"booking_id" BIGINT NOT NULL,
	-- Position within the booking, 1 upward. Used on tickets and by every legacy interchange format.
	"passenger_sequence" SMALLINT NOT NULL,
	-- ADT | CHD | INF. Infants without a seat are passengers who consume no inventory, which is why type is not derivable from age alone.
	"passenger_type" VARCHAR(8) NOT NULL DEFAULT 'ADT',
	-- First name exactly as it appears on the travel document.
	"given_name" VARCHAR(80) NOT NULL,
	-- Surname exactly as on the document. A mismatch at check-in is a denied boarding, so this is not a display field.
	"family_name" VARCHAR(80) NOT NULL,
	-- Required for infants, children and most international itineraries.
	"date_of_birth" DATE,
	-- Passport or ID number, collected for international travel.
	"document_number" VARCHAR(64),
	-- Issuing country of the travel document.
	"document_country_code" CHAR(2),
	-- Document expiry, checked against the arrival date at check-in.
	"document_expires_on" DATE,
	-- Loyalty number, which decides mileage accrual and boarding priority.
	"frequent_flyer_number" VARCHAR(32),
	-- Comma-separated SSR codes, e.g. WCHR,VGML. Coded so they survive translation and interline transfer.
	"special_service_codes" VARCHAR(120),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "passengers" IS 'A named traveller on one booking, not a user account. The same human booked twice is two rows, because the name on the ticket must match the document presented on that day and later profile edits must never rewrite it.';
COMMENT ON COLUMN "passengers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "passengers"."booking_id" IS 'Booking the passenger travels under.';
COMMENT ON COLUMN "passengers"."passenger_sequence" IS 'Position within the booking, 1 upward. Used on tickets and by every legacy interchange format.';
COMMENT ON COLUMN "passengers"."passenger_type" IS 'ADT | CHD | INF. Infants without a seat are passengers who consume no inventory, which is why type is not derivable from age alone.';
COMMENT ON COLUMN "passengers"."given_name" IS 'First name exactly as it appears on the travel document.';
COMMENT ON COLUMN "passengers"."family_name" IS 'Surname exactly as on the document. A mismatch at check-in is a denied boarding, so this is not a display field.';
COMMENT ON COLUMN "passengers"."date_of_birth" IS 'Required for infants, children and most international itineraries.';
COMMENT ON COLUMN "passengers"."document_number" IS 'Passport or ID number, collected for international travel.';
COMMENT ON COLUMN "passengers"."document_country_code" IS 'Issuing country of the travel document.';
COMMENT ON COLUMN "passengers"."document_expires_on" IS 'Document expiry, checked against the arrival date at check-in.';
COMMENT ON COLUMN "passengers"."frequent_flyer_number" IS 'Loyalty number, which decides mileage accrual and boarding priority.';
COMMENT ON COLUMN "passengers"."special_service_codes" IS 'Comma-separated SSR codes, e.g. WCHR,VGML. Coded so they survive translation and interline transfer.';

CREATE UNIQUE INDEX "uq_passengers_booking_sequence"
ON "passengers" ("booking_id", "passenger_sequence");
CREATE INDEX "idx_passengers_name"
ON "passengers" ("family_name", "given_name");

CREATE TABLE IF NOT EXISTS "booking_segments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Booking the segment belongs to. Segments are shared by everyone on the PNR.
	"booking_id" BIGINT NOT NULL,
	-- Order in the itinerary, 1 upward, including connections.
	"segment_sequence" SMALLINT NOT NULL,
	-- Dated leg being flown.
	"departure_id" BIGINT NOT NULL,
	-- Class the segment was sold in, which fixes the rules for the whole segment.
	"fare_class_id" BIGINT NOT NULL,
	-- confirmed | waitlisted | cancelled | flown | no_show. Segments fail individually, which is why this is not a booking-level column.
	"status" VARCHAR(16) NOT NULL DEFAULT 'confirmed',
	-- True when the segment continues an itinerary rather than starting one, which changes the minimum connect time rules that apply.
	"is_connection" BOOLEAN NOT NULL DEFAULT false,
	-- Airline whose code is on the ticket. Differs from the operating carrier on a codeshare, and passengers complain about exactly that difference.
	"marketing_carrier" CHAR(2) NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "booking_segments" IS 'The itinerary, one row per flown leg, attached to the booking rather than to each passenger. Four travellers on a two-leg trip are two segment rows, not eight, and a schedule change touches those two rows once.';
COMMENT ON COLUMN "booking_segments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "booking_segments"."booking_id" IS 'Booking the segment belongs to. Segments are shared by everyone on the PNR.';
COMMENT ON COLUMN "booking_segments"."segment_sequence" IS 'Order in the itinerary, 1 upward, including connections.';
COMMENT ON COLUMN "booking_segments"."departure_id" IS 'Dated leg being flown.';
COMMENT ON COLUMN "booking_segments"."fare_class_id" IS 'Class the segment was sold in, which fixes the rules for the whole segment.';
COMMENT ON COLUMN "booking_segments"."status" IS 'confirmed | waitlisted | cancelled | flown | no_show. Segments fail individually, which is why this is not a booking-level column.';
COMMENT ON COLUMN "booking_segments"."is_connection" IS 'True when the segment continues an itinerary rather than starting one, which changes the minimum connect time rules that apply.';
COMMENT ON COLUMN "booking_segments"."marketing_carrier" IS 'Airline whose code is on the ticket. Differs from the operating carrier on a codeshare, and passengers complain about exactly that difference.';

CREATE UNIQUE INDEX "uq_segments_booking_sequence"
ON "booking_segments" ("booking_id", "segment_sequence");
CREATE INDEX "idx_segments_departure_status"
ON "booking_segments" ("departure_id", "status");

CREATE TABLE IF NOT EXISTS "tickets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Booking the ticket was issued against. Kept even after an exchange moves the passenger to a different PNR.
	"booking_id" BIGINT NOT NULL,
	-- Traveller the ticket names. One ticket covers one passenger across every segment of the itinerary.
	"passenger_id" BIGINT NOT NULL,
	-- Thirteen-digit e-ticket number: three-digit airline prefix plus ten digits. This, not the record locator, is the financial document.
	"ticket_number" VARCHAR(16) NOT NULL UNIQUE,
	-- open | used | exchanged | refunded | void | suspended. Coupon-level in real systems; simplified to one status per ticket here.
	"status" VARCHAR(24) NOT NULL DEFAULT 'open',
	-- Base fare in minor units, before taxes and fees.
	"fare_minor" INTEGER NOT NULL,
	-- Government and airport charges, which are refundable under different rules than the fare itself.
	"taxes_minor" INTEGER NOT NULL DEFAULT 0,
	-- Currency of issue.
	"currency_code" CHAR(3) NOT NULL,
	-- Issue time. A ticket cannot be issued before payment clears.
	"issued_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Replacement ticket when the itinerary changed. A change reissues rather than edits, so the chain of tickets is the audit trail of the change.
	"exchanged_for_ticket_id" BIGINT,
	-- Refund time. Null unless the value was returned.
	"refunded_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tickets" IS 'The money document, one per passenger. The booking holds the seats; the ticket holds the value. Changing a trip never edits a ticket, it issues a new one and points the old row at it, which is why exchanged_for_ticket_id is a self-reference.';
COMMENT ON COLUMN "tickets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "tickets"."booking_id" IS 'Booking the ticket was issued against. Kept even after an exchange moves the passenger to a different PNR.';
COMMENT ON COLUMN "tickets"."passenger_id" IS 'Traveller the ticket names. One ticket covers one passenger across every segment of the itinerary.';
COMMENT ON COLUMN "tickets"."ticket_number" IS 'Thirteen-digit e-ticket number: three-digit airline prefix plus ten digits. This, not the record locator, is the financial document.';
COMMENT ON COLUMN "tickets"."status" IS 'open | used | exchanged | refunded | void | suspended. Coupon-level in real systems; simplified to one status per ticket here.';
COMMENT ON COLUMN "tickets"."fare_minor" IS 'Base fare in minor units, before taxes and fees.';
COMMENT ON COLUMN "tickets"."taxes_minor" IS 'Government and airport charges, which are refundable under different rules than the fare itself.';
COMMENT ON COLUMN "tickets"."currency_code" IS 'Currency of issue.';
COMMENT ON COLUMN "tickets"."issued_at" IS 'Issue time. A ticket cannot be issued before payment clears.';
COMMENT ON COLUMN "tickets"."exchanged_for_ticket_id" IS 'Replacement ticket when the itinerary changed. A change reissues rather than edits, so the chain of tickets is the audit trail of the change.';
COMMENT ON COLUMN "tickets"."refunded_at" IS 'Refund time. Null unless the value was returned.';

CREATE INDEX "idx_tickets_passenger"
ON "tickets" ("passenger_id");
CREATE INDEX "idx_tickets_status"
ON "tickets" ("status");

CREATE TABLE IF NOT EXISTS "seat_assignments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Segment the seat applies to. A seat is per leg, so a connecting passenger has one row per leg.
	"segment_id" BIGINT NOT NULL,
	-- Traveller occupying the seat.
	"passenger_id" BIGINT NOT NULL,
	-- Seat in the layout assigned to that departure.
	"seat_id" BIGINT NOT NULL,
	-- When it was taken.
	"assigned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- passenger | agent | auto | reaccommodation. Auto-assigned seats can be moved freely; paid ones cannot.
	"assigned_by" VARCHAR(16) NOT NULL DEFAULT 'passenger',
	-- True when the seat was bought, in which case there is a matching ancillaries row and the airline owes a refund if it moves the passenger.
	"is_paid" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "seat_assignments" IS 'Who sits where on one dated leg. The two unique constraints do all the work: a seat cannot be double-assigned and a passenger cannot hold two seats on the same leg. Equipment swaps invalidate rows here, which is why nothing else depends on them.';
COMMENT ON COLUMN "seat_assignments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "seat_assignments"."segment_id" IS 'Segment the seat applies to. A seat is per leg, so a connecting passenger has one row per leg.';
COMMENT ON COLUMN "seat_assignments"."passenger_id" IS 'Traveller occupying the seat.';
COMMENT ON COLUMN "seat_assignments"."seat_id" IS 'Seat in the layout assigned to that departure.';
COMMENT ON COLUMN "seat_assignments"."assigned_at" IS 'When it was taken.';
COMMENT ON COLUMN "seat_assignments"."assigned_by" IS 'passenger | agent | auto | reaccommodation. Auto-assigned seats can be moved freely; paid ones cannot.';
COMMENT ON COLUMN "seat_assignments"."is_paid" IS 'True when the seat was bought, in which case there is a matching ancillaries row and the airline owes a refund if it moves the passenger.';

CREATE UNIQUE INDEX "uq_seat_assignments_segment_seat"
ON "seat_assignments" ("segment_id", "seat_id");
CREATE UNIQUE INDEX "uq_seat_assignments_segment_passenger"
ON "seat_assignments" ("segment_id", "passenger_id");

CREATE TABLE IF NOT EXISTS "ancillaries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Booking the extra was bought on.
	"booking_id" BIGINT NOT NULL,
	-- Traveller it belongs to. Null for items bought for the whole party, such as a lounge pass for everyone.
	"passenger_id" BIGINT,
	-- Segment it applies to. Null for whole-itinerary items like travel insurance.
	"segment_id" BIGINT,
	-- Seat purchased, when the ancillary is a paid seat. This is the link that makes a refund for an involuntary seat change computable.
	"seat_assignment_id" BIGINT,
	-- checked_bag | excess_weight | paid_seat | meal | lounge | priority_boarding | pet | sports_equipment | insurance.
	"kind" VARCHAR(32) NOT NULL,
	-- Units bought, e.g. two extra bags.
	"quantity" SMALLINT NOT NULL DEFAULT 1,
	-- Total charged in minor units, snapshotted so a later price change cannot rewrite the receipt.
	"amount_minor" INTEGER NOT NULL,
	-- Currency of amount_minor.
	"currency_code" CHAR(3) NOT NULL,
	-- purchased | delivered | refunded | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'purchased',
	-- Purchase time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ancillaries" IS 'Everything sold that is not the fare, and on many carriers most of the margin. The three nullable foreign keys are deliberate: an extra bag is per passenger per segment, a paid seat points at the assignment, and insurance is per booking.';
COMMENT ON COLUMN "ancillaries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ancillaries"."booking_id" IS 'Booking the extra was bought on.';
COMMENT ON COLUMN "ancillaries"."passenger_id" IS 'Traveller it belongs to. Null for items bought for the whole party, such as a lounge pass for everyone.';
COMMENT ON COLUMN "ancillaries"."segment_id" IS 'Segment it applies to. Null for whole-itinerary items like travel insurance.';
COMMENT ON COLUMN "ancillaries"."seat_assignment_id" IS 'Seat purchased, when the ancillary is a paid seat. This is the link that makes a refund for an involuntary seat change computable.';
COMMENT ON COLUMN "ancillaries"."kind" IS 'checked_bag | excess_weight | paid_seat | meal | lounge | priority_boarding | pet | sports_equipment | insurance.';
COMMENT ON COLUMN "ancillaries"."quantity" IS 'Units bought, e.g. two extra bags.';
COMMENT ON COLUMN "ancillaries"."amount_minor" IS 'Total charged in minor units, snapshotted so a later price change cannot rewrite the receipt.';
COMMENT ON COLUMN "ancillaries"."currency_code" IS 'Currency of amount_minor.';
COMMENT ON COLUMN "ancillaries"."status" IS 'purchased | delivered | refunded | cancelled.';
COMMENT ON COLUMN "ancillaries"."created_at" IS 'Purchase time.';

CREATE INDEX "idx_ancillaries_booking_kind"
ON "ancillaries" ("booking_id", "kind");
CREATE INDEX "idx_ancillaries_passenger"
ON "ancillaries" ("passenger_id");

